// Accepts a single post, a { posts: [...] } batch, or direct sub-workflow items.
const norm = (v) => String(v ?? '').trim();
const out = [];

for (const item of $input.all()) {
  const j = item.json ?? {};
  const payload = (j.body && typeof j.body === 'object') ? j.body : j;
  const list = Array.isArray(payload.posts) ? payload.posts : [payload];

  for (const p of list) {
    const postId = norm(p.postId || p.Post_ID);
    const query  = norm(p.query || p.storyTopic || p.Story_Topic || p.title);
    if (!postId || !query) continue;
    out.push({ json: { postId, query, publicId: `damu-linkedin/${postId}` } });
  }
}

if (!out.length) return [{ json: { _empty: true, message: 'Need at least one { postId, query }' } }];
return out;

const MIN_WIDTH = 600;
// Hosts that block hotlinking, or that serve watermarked previews of paid stock.
const BAD_HOSTS = [
  'lookaside.', 'fbsbx.com', 'instagram.f', 'x.com', 'twimg.com',
  'dreamstime.com', 'shutterstock.com', 'alamy.com', 'gettyimages.',
  'istockphoto.com', '123rf.com', 'depositphotos.com', 'stock.adobe.com',
  'agefotostock.com', 'canstockphoto.', 'vectorstock.com', 'watermark.',
];

const planned = $('Normalize Input').all().map(i => i.json);
const inputs  = $input.all();
const out = [];

for (let i = 0; i < inputs.length; i++) {
  const plan = planned[i] ?? {};
  const res  = inputs[i].json ?? {};
  const list = Array.isArray(res.images_results) ? res.images_results : [];

  const usable = list.filter(r => {
    const u = String(r.original ?? '');
    if (!/^https:\/\//i.test(u)) return false;
    if (BAD_HOSTS.some(h => u.includes(h))) return false;
    if (r.original_width && Number(r.original_width) < MIN_WIDTH) return false;
    return true;
  });

  const hit = usable[0];

  if (!hit) {
    out.push({ json: { ...plan, found: false, reason: res?.error ?? 'no usable image in search results' } });
    continue;
  }

  out.push({ json: {
    ...plan,
    found: true,
    file: hit.original,
    sourcePage: hit.link ?? '',
    sourceSite: hit.source ?? '',
    sourceTitle: hit.title ?? '',
    width: hit.original_width ?? null,
    height: hit.original_height ?? null,
  } });
}

return out;

const CLOUD = 'yto9u5lp';
const planned = $('Pick Best Result').all().map(i => i.json);
const byId = {};
for (const p of planned) byId[p.postId] = p;

const results = {};
const inputs = $input.all();

for (let i = 0; i < inputs.length; i++) {
  const j = inputs[i].json ?? {};

  // Rows that never found an image arrive here straight from the IF false branch.
  if (j.found === false) {
    results[j.postId] = { postId: j.postId, imageUrl: '', imageSource: 'none', reason: j.reason ?? 'not found' };
    continue;
  }

  const pid = String(j.public_id ?? '');
  const postId = pid.includes('/') ? pid.split('/').pop() : (j.postId || planned[i]?.postId || '');
  const plan = byId[postId] ?? planned[i] ?? {};

  if (j.secure_url) {
    results[postId] = {
      postId,
      imageUrl: `https://res.cloudinary.com/${CLOUD}/image/upload/f_jpg,q_auto:good,w_1200,h_1200,c_fit/${pid}.jpg`,
      imageSource: 'google_search',
      sourcePage: plan.sourcePage ?? '',
      sourceSite: plan.sourceSite ?? '',
    };
  } else if (postId) {
    results[postId] = {
      postId,
      imageUrl: '',
      imageSource: 'none',
      reason: j?.error?.message ?? j?.message ?? 'Cloudinary upload failed',
      sourcePage: plan.sourcePage ?? '',
    };
  }
}

for (const p of planned) {
  if (!results[p.postId]) results[p.postId] = { postId: p.postId, imageUrl: '', imageSource: 'none', reason: p.reason ?? 'unresolved' };
}

const out = Object.values(results);
console.log(out.map(r => `${r.postId}: ${r.imageSource} ${r.imageUrl || '(' + (r.reason || 'none') + ')'}`).join('\n'));
return out.map(json => ({ json }));
